draw:
var dcm = p.d, q = p.q;
var planeY = H * 0.50;
var per = (H * 0.40) / 12.0;      // pixels per cm
var cx = W * 0.5;
var X = function (x) { return cx + x * per; };
var Y = function (y) { return planeY - y * per; };
var Yc = Y(dcm);

ctx.lineWidth = 1;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

// field lines traced through the two-charge field
var nLines = 11;
var lines = [];
var i, j;
for (i = 0; i < nLines; i++) {
  var ang = -Math.PI * 0.5 + Math.PI * 0.98 * (i + 0.5) / nLines;
  var px0 = 0.35 * Math.sin(ang), py0 = dcm - 0.35 * Math.cos(ang);
  var pts = [];
  var xx = px0, yy = py0;
  for (j = 0; j < 700; j++) {
    pts.push([X(xx), Y(yy)]);
    if (yy <= 0.02) break;
    var ax = xx, ay = yy - dcm, bx = xx, by = yy + dcm;
    var ra = Math.pow(ax * ax + ay * ay, 1.5);
    var rb = Math.pow(bx * bx + by * by, 1.5);
    if (ra < 1e-6 || rb < 1e-6) break;
    var ex = ax / ra - bx / rb, ey = ay / ra - by / rb;
    var m = Math.sqrt(ex * ex + ey * ey);
    if (m < 1e-9) break;
    xx += 0.12 * ex / m; yy += 0.12 * ey / m;
    if (Math.abs(xx) > (W / per)) break;
  }
  lines.push(pts);
}
ctx.strokeStyle = C.faint;
for (i = 0; i < lines.length; i++) {
  ctx.beginPath();
  for (j = 0; j < lines[i].length; j++) {
    if (j === 0) ctx.moveTo(lines[i][j][0], lines[i][j][1]);
    else ctx.lineTo(lines[i][j][0], lines[i][j][1]);
  }
  ctx.stroke();
}
// markers drifting outward along the lines
var frac = (t * 0.35) % 1;
ctx.fillStyle = C.figure;
for (i = 0; i < lines.length; i++) {
  var k = Math.floor(frac * (lines[i].length - 1));
  ctx.beginPath();
  ctx.arc(lines[i][k][0], lines[i][k][1], 2, 0, Math.PI * 2);
  ctx.fill();
}

// the conductor surface
ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(0, planeY); ctx.lineTo(W, planeY); ctx.stroke();
ctx.lineWidth = 1;
ctx.fillStyle = C.ink;
ctx.fillText("grounded plane, V = 0", 8, planeY - 6);

// induced surface density, drawn downward from the plane
var sig0 = q * 1e4 / (2 * Math.PI * dcm * dcm);   // nC/m^2
var amp = H * 0.30;
ctx.strokeStyle = C.accent;
ctx.beginPath();
for (i = 0; i <= 160; i++) {
  var sx = (-W / 2 + W * i / 160) / per;          // cm
  var f = Math.pow(dcm * dcm / (sx * sx + dcm * dcm), 1.5);
  var yy2 = planeY + 6 + amp * f;
  if (i === 0) ctx.moveTo(X(sx), yy2); else ctx.lineTo(X(sx), yy2);
}
ctx.stroke();
ctx.fillStyle = C.accent;
ctx.fillText("induced sigma, negative everywhere", 8, planeY + amp + 26);

// real charge
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(cx, Yc, 6, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.paper;
ctx.fillText("+", cx - 3, Yc + 4);
ctx.fillStyle = C.ink;
ctx.fillText("+q at height d", cx + 12, Yc - 4);

// image charge
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(cx, Yc); ctx.lineTo(cx, Y(-dcm)); ctx.stroke();
ctx.beginPath(); ctx.arc(cx, Y(-dcm), 6, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.rule;
ctx.fillText("image -q, depth d", cx + 12, Y(-dcm) + 4);

// force arrow on the real charge
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(cx - 26, Yc); ctx.lineTo(cx - 26, Yc + 22); ctx.stroke();
ctx.beginPath();
ctx.moveTo(cx - 26, Yc + 26); ctx.lineTo(cx - 31, Yc + 17); ctx.lineTo(cx - 21, Yc + 17);
ctx.closePath(); ctx.fillStyle = C.figure; ctx.fill();
ctx.lineWidth = 1;
ctx.fillText("F", cx - 44, Yc + 16);

var F = 22.475 * q * q / (dcm * dcm);             // microN
var U = -0.22475 * q * q / dcm;                   // microJ
out.note = "d = " + dcm.toFixed(1) + " cm, q = " + q.toFixed(1) + " nC   |   F = " +
  F.toFixed(2) + " uN toward the plane, peak sigma = " + (-sig0).toFixed(0) +
  " nC/m^2, U = " + U.toFixed(3) + " uJ";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;
var cx = W * 0.5, cy = H * 0.5;
var a = Math.min(W, H) * 0.19;

// the two grounded planes, drawn through the corner
ctx.strokeStyle = C.ink;
ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(cx, 4); ctx.lineTo(cx, H - 4); ctx.stroke();
ctx.beginPath(); ctx.moveTo(4, cy); ctx.lineTo(W - 4, cy); ctx.stroke();
ctx.lineWidth = 1;
ctx.fillStyle = C.ink;
ctx.fillText("grounded planes, V = 0", 8, 14);

var q = [
  [cx + a, cy - a, "+q", 1],
  [cx - a, cy - a, "-q", 0],
  [cx + a, cy + a, "-q", 0],
  [cx - a, cy + a, "+q", 1]
];
var i;
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
for (i = 1; i < 4; i++) {
  ctx.beginPath(); ctx.moveTo(q[0][0], q[0][1]); ctx.lineTo(q[i][0], q[i][1]); ctx.stroke();
}
ctx.setLineDash([]);

for (i = 0; i < 4; i++) {
  var col = i === 0 ? C.accent : C.rule;
  ctx.fillStyle = col;
  ctx.beginPath(); ctx.arc(q[i][0], q[i][1], 7, 0, Math.PI * 2);
  if (i === 0) ctx.fill(); else { ctx.strokeStyle = col; ctx.stroke(); }
  ctx.fillStyle = i === 0 ? C.paper : col;
  ctx.fillText(q[i][3] === 1 ? "+" : "-", q[i][0] - 3, q[i][1] + 4);
  ctx.fillStyle = C.ink;
  var lab = i === 0 ? "real charge +q" : "image " + q[i][2];
  ctx.fillText(lab, q[i][0] - 34, q[i][1] - 12);
}

// distance labels
ctx.fillStyle = C.ink;
ctx.fillText("a", q[0][0] - a * 0.55, cy - 6);
ctx.fillText("a", cx + 6, cy - a * 0.5);

// forces on the real charge: two attractions, one repulsion
function arrow(x0, y0, dx, dy, label) {
  var m = Math.sqrt(dx * dx + dy * dy);
  var ux = dx / m, uy = dy / m;
  ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x0 + dx, y0 + dy); ctx.stroke();
  ctx.fillStyle = C.figure;
  ctx.beginPath();
  ctx.moveTo(x0 + dx + ux * 5, y0 + dy + uy * 5);
  ctx.lineTo(x0 + dx - uy * 4, y0 + dy + ux * 4);
  ctx.lineTo(x0 + dx + uy * 4, y0 + dy - ux * 4);
  ctx.closePath(); ctx.fill();
  ctx.lineWidth = 1;
  ctx.fillText(label, x0 + dx + ux * 10 - 8, y0 + dy + uy * 10 + 10);
}
var s = a * 0.62;
arrow(q[0][0], q[0][1], -s, 0, "pull");
arrow(q[0][0], q[0][1], 0, s, "pull");
arrow(q[0][0], q[0][1], s * 0.5, -s * 0.5, "push");

ctx.fillStyle = C.accent;
ctx.fillText("net force points into the corner", W * 0.52, H - 10);
out.note = "three images: -q on each side, +q on the diagonal. Net force magnitude 0.229 k q squared over a squared.";

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.lineWidth = 1;
var R = 5.0, a = p.a, q = p.q, extra = p.centre;
var cx = W * 0.30, cy = H * 0.52;
var per = Math.min((W * 0.62) / 26.0, (H * 0.36) / R);
var X = function (x) { return cx + x * per; };

// the sphere
ctx.strokeStyle = C.ink; ctx.lineWidth = 2;
ctx.beginPath(); ctx.arc(cx, cy, R * per, 0, Math.PI * 2); ctx.stroke();
ctx.lineWidth = 1;
ctx.fillStyle = C.ink;
ctx.fillText("conductor, radius R = 5.0 cm", cx - R * per, cy - R * per - 10);

// axis
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(4, cy); ctx.lineTo(W - 4, cy); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.beginPath(); ctx.arc(cx, cy, 2.5, 0, Math.PI * 2); ctx.fill();
ctx.fillText("centre", cx - 16, cy + 18);

// image
var b = R * R / a;
var qp = -R * q / a;

ctx.strokeStyle = C.rule; ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(X(b), cy); ctx.lineTo(X(a), cy); ctx.stroke();
ctx.setLineDash([]);

ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.arc(X(b), cy, 6, 0, Math.PI * 2); ctx.stroke();
ctx.fillStyle = C.rule;
ctx.fillText("-", X(b) - 2, cy + 4);
ctx.fillStyle = C.ink;
ctx.fillText("image at b = R squared over a", X(b) - 30, cy - 14);

if (extra > 0.5) {
  ctx.strokeStyle = C.figure;
  ctx.beginPath(); ctx.arc(cx, cy, 6, 0, Math.PI * 2); ctx.stroke();
  ctx.fillStyle = C.figure;
  ctx.fillText("+", cx - 3, cy + 4);
  ctx.fillText("centre image", cx - 62, cy + 34);
}

// real charge
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(X(a), cy, 7, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.paper;
ctx.fillText("+", X(a) - 3, cy + 4);
ctx.fillStyle = C.ink;
ctx.fillText("real charge q", X(a) - 34, cy - 16);

// force arrow on the real charge
var kq2 = 8.99e-5 * q * q;                       // gives newtons with cm inputs
var F1 = -kq2 * R * a / Math.pow(a * a - R * R, 2);
var F2 = extra > 0.5 ? kq2 * R / (a * a * a) : 0;
var Fn = F1 + F2;                                // negative means attraction
var dir = Fn < 0 ? -1 : 1;
var len = Math.min(52, 14 + Math.abs(Fn) * 4e7);
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath(); ctx.moveTo(X(a), cy + 24); ctx.lineTo(X(a) + dir * len, cy + 24); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.beginPath();
ctx.moveTo(X(a) + dir * (len + 6), cy + 24);
ctx.lineTo(X(a) + dir * len, cy + 19);
ctx.lineTo(X(a) + dir * len, cy + 29);
ctx.closePath(); ctx.fill();
ctx.lineWidth = 1;
ctx.fillText(Fn < 0 ? "attracted" : "repelled", X(a) - 20, cy + 44);

out.note = "a = " + a.toFixed(1) + " cm, image charge " + qp.toFixed(3) + " nC at b = " +
  b.toFixed(2) + " cm   |   net force " + (Math.abs(Fn) * 1e9).toFixed(0) + " nN " +
  (Fn < 0 ? "attractive" : "repulsive") + (extra > 0.5 ? " (isolated neutral sphere)" : " (grounded sphere)");
